import type { RenderMode, Schema, SchemaType } from "./types.js";

// How each type's pages are generated (docs/TOOLKITS.md, "options.render").
// A server that does not deliver `render` yet means every type is static.

export const RENDER_MODES: readonly RenderMode[] = ["static", "revalidate", "dynamic"];

/** The render mode of a type: its `render` from the schema, "static" when missing or unknown. */
export function renderMode(schema: Pick<Schema, "types">, type: string | Pick<SchemaType, "render">): RenderMode {
  const def = typeof type === "string" ? schema.types.find((t) => t.apiId === type) : type;
  const mode = def?.render;
  return mode && RENDER_MODES.includes(mode) ? mode : "static";
}

/** Whether a type's pages are built ahead of time (static or revalidate) rather than per request. */
export const isPrerendered = (schema: Pick<Schema, "types">, type: string | Pick<SchemaType, "render">) => renderMode(schema, type) !== "dynamic";

/** The types that have pages of their own (a URL pattern). */
export const routedTypes = (schema: Pick<Schema, "types">) => schema.types.filter((t) => !!t.urlPattern);
